69	void SentryWriter::initialize(Poco::Util::LayeredConfiguration & config)
70	{
71	    bool enabled = false;
72	    bool debug = config.getBool("send_crash_reports.debug", false);
73	    auto * logger = &Poco::Logger::get("SentryWriter");
74	
75	    if (config.getBool("send_crash_reports.enabled", false))
76	    {
77	        if (debug || (strlen(VERSION_OFFICIAL) > 0)) //-V560
78	            enabled = true;
79	    }
80	
81	    if (enabled)
82	    {
83	        server_data_path = config.getString("path", "");
84	        const std::filesystem::path & default_tmp_path = fs::path(config.getString("tmp_path", fs::temp_directory_path())) / "sentry";
85	        const std::string & endpoint
86	            = config.getString("send_crash_reports.endpoint");
87	        const std::string & temp_folder_path
88	            = config.getString("send_crash_reports.tmp_path", default_tmp_path);
89	        fs::create_directories(temp_folder_path);
90	
91	        sentry_options_t * options = sentry_options_new();  /// will be freed by sentry_init or sentry_shutdown
92	        sentry_options_set_release(options, VERSION_STRING_SHORT);
93	        if (debug)
94	        {
95	            sentry_options_set_debug(options, 1);
96	        }
97	        sentry_options_set_dsn(options, endpoint.c_str());
98	        sentry_options_set_database_path(options, temp_folder_path.c_str());
99	        if (strstr(VERSION_DESCRIBE, "-stable") || strstr(VERSION_DESCRIBE, "-lts"))
100	        {
101	            sentry_options_set_environment(options, "prod");
102	        }
103	        else
104	        {
105	            sentry_options_set_environment(options, "test");
106	        }
107	
108	        const std::string & http_proxy = config.getString("send_crash_reports.http_proxy", "");
109	        if (!http_proxy.empty())
110	        {
111	            sentry_options_set_http_proxy(options, http_proxy.c_str());
112	        }
113	
114	        int init_status = sentry_init(options);
115	        if (!init_status)
116	        {
117	            initialized = true;
118	            anonymize = config.getBool("send_crash_reports.anonymize", false);
119	            LOG_INFO(
120	                logger,
121	                "Sending crash reports is initialized with {} endpoint and {} temp folder{}",
122	                endpoint,
123	                temp_folder_path,
124	                anonymize ? " (anonymized)" : "");
125	        }
126	        else
127	        {
128	            LOG_WARNING(logger, "Sending crash reports failed to initialize with {} status", init_status);
129	        }
130	    }
131	    else
132	    {
133	        LOG_INFO(logger, "Sending crash reports is disabled");
134	    }
